def transform(grid):
    from collections import defaultdict
    groups=defaultdict(list)
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v: groups[v].append((r,c))
    pieces=[]
    for v,pts in groups.items():
        mr=min(r for r,c in pts); mc=min(c for r,c in pts)
        p=[(r-mr,c-mc) for r,c in pts]
        pieces.append((v,p,max(r for r,c in p)+1,max(c for r,c in p)+1))
    n=sum(len(p) for v,p,h,w in pieces)
    dims=[(h,n//h) for h in range(1,n+1) if n%h==0]
    dims.sort(key=lambda hw:(sum(hw),abs(hw[0]-hw[1]),hw[0]))
    for H,W in dims:
        if any(h>H or w>W for v,p,h,w in pieces): continue
        covers=[[] for _ in range(n)]
        for i,(v,p,h,w) in enumerate(pieces):
            for r in range(H-h+1):
                for c in range(W-w+1):
                    cells=[(r+a)*W+c+b for a,b in p]
                    mask=sum(1<<x for x in cells)
                    ent=(i,mask,cells)
                    for x in cells: covers[x].append(ent)
        full=(1<<n)-1
        failed=set()
        def solve(occ,used):
            if occ==full: return []
            key=(occ,used)
            if key in failed: return None
            opts=None
            for x in range(n):
                if occ>>x&1: continue
                avail=[e for e in covers[x] if not (used>>e[0]&1) and not(e[1]&occ)]
                if not avail:
                    failed.add(key); return None
                if opts is None or len(avail)<len(opts): opts=avail
                if len(opts)==1: break
            for i,m,cells in opts:
                res=solve(occ|m,used|(1<<i))
                if res is not None: return [(i,cells)]+res
            failed.add(key)
            return None
        result=solve(0,0)
        if result is not None:
            out=[[0]*W for _ in range(H)]
            for i,cells in result:
                for x in cells: out[x//W][x%W]=pieces[i][0]
            return out
    return [row[:] for row in grid]

